"""Adaptive relevel-before-loading, opposite-end pinch and translation-only loaded lift."""
import numpy as np
from dojo.skills import basket_first as B,basket_transfer as T,grasps as G

def install(low=False):
 T.slerp_R=lambda R0,R1,f:R0.copy()
 level0=B.level_hold
 def level(sk,container,arm,R,xy,bottom):
  if not hasattr(sk,'r3_initial_hold'):sk.r3_initial_hold=(container,R.copy(),xy)
  return level0(sk,container,arm,R,xy,bottom)
 B.level_hold=level
 translate0=B.translate
 def translate(sk,arm,dz,name,hold=5):
  if low and name=='lower in air':dz=-.08
  ok=translate0(sk,arm,dz,name,hold)
  if ok and name=='lower in air':
   container,R,xy=sk.r3_initial_hold;bottom=.775 if low else sk.refresh().obj(container).bottom_z
   for _ in range(2):
    reached,z,tilt=level0(sk,container,arm,R,xy,bottom)
    if not reached:return False
    if tilt<5:break
  return ok
 B.translate=translate
 grasps0=G.box_rim_grasps
 def grasps(obj,kin,arm,**kw):
  gs=grasps0(obj,kin,arm,**kw)
  if kw.get('depth')==.025:
   other='right' if arm=='left' else 'left';u=kin.base(arm)[:2,3]-kin.base(other)[:2,3];u/=np.linalg.norm(u)
   gs=[g for g in gs if (g.T[:2,3]-obj.center_w[:2])@u>.10]
  return gs
 G.box_rim_grasps=grasps
